import java.util.*;
import java.io.*;

public class Main {
    static final long INF_VAL = (long)1e9 + 9;
    static int s, t, n, m, T;
    static List<List<Integer>> adj;
    static List<Edge> edges;
    static String[] sci = new String[101], reac = new String[101];
    static int[][] turnsUnusable = new int[10][10];
    static int[][] visited = new int[101][101];
    static boolean[][][][] reach = new boolean[10][10][10][10];

    static class Edge {
        int u, v;
        long flow, capacity;

        Edge(int u, int v, long flow, long capacity) {
            this.u = u;
            this.v = v;
            this.flow = flow;
            this.capacity = capacity;
        }
    }

    static boolean validPos(int r, int c) {
        return r >= 0 && c >= 0 && r < n && c < m;
    }

    static int getID(int x, int y) {
        return 1 + m * x + y;
    }

    static void addEdge(int u, int v, int cap) {
        adj.get(u).add(edges.size());
        edges.add(new Edge(u, v, 0, cap));
        adj.get(v).add(edges.size());
        edges.add(new Edge(v, u, 0, 0));
    }

    static boolean bfs() {
        int[] dist = new int[adj.size()];
        Arrays.fill(dist, -1);
        dist[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int id : adj.get(u)) {
                Edge e = edges.get(id);
                int v = e.v;
                if (dist[v] == -1 && e.flow < e.capacity) {
                    dist[v] = dist[u] + 1;
                    q.offer(v);
                    if (v == t) return true;
                }
            }
        }
        return false;
    }

    static long pushFlow(int u, long flow, int[] ptr, int[] dist) {
        if (flow == 0 || u == t) return flow;
        for (; ptr[u] < adj.get(u).size(); ++ptr[u]) {
            int id = adj.get(u).get(ptr[u]);
            Edge e = edges.get(id);
            int v = e.v;
            if (dist[v] == dist[u] + 1 && e.flow < e.capacity) {
                long pushed = pushFlow(v, Math.min(flow, e.capacity - e.flow), ptr, dist);
                if (pushed > 0) {
                    e.flow += pushed;
                    edges.get(id ^ 1).flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    static long maxFlow() {
        long total = 0;
        while (true) {
            int[] dist = new int[adj.size()];
            Arrays.fill(dist, -1);
            if (!bfs()) break;
            int[] ptr = new int[adj.size()];
            while (true) {
                long pushed = pushFlow(s, Long.MAX_VALUE, ptr, dist);
                if (pushed == 0) break;
                total += pushed;
            }
        }
        return total;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int T_input = Integer.parseInt(br.readLine().trim());
        T = T_input + 1;
        n = m = Integer.parseInt(br.readLine().trim());
        adj = new ArrayList<>();
        for (int i = 0; i <= 2 * m * m + 1; i++) {
            adj.add(new ArrayList<>());
        }
        edges = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            sci[i] = br.readLine().trim();
        }
        for (int i = 0; i < n; i++) {
            reac[i] = br.readLine().trim();
            for (int j = 0; j < m; j++) {
                turnsUnusable[i][j] = (int) INF_VAL;
            }
        }
        // BFS for 'Z'
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (reac[i].charAt(j) == 'Z') {
                    Queue<int[]> q = new LinkedList<>();
                    q.offer(new int[]{i, j});
                    turnsUnusable[i][j] = 1;
                    while (!q.isEmpty()) {
                        int[] pos = q.poll();
                        int x = pos[0], y = pos[1];
                        for (int dx = -1; dx <= 1; dx++) {
                            for (int dy = -1; dy <= 1; dy++) {
                                if (Math.abs(dx) + Math.abs(dy) == 1) {
                                    int nx = x + dx, ny = y + dy;
                                    if (validPos(nx, ny) && turnsUnusable[nx][ny] == (int) INF_VAL && sci[nx].charAt(ny) != 'Y') {
                                        turnsUnusable[nx][ny] = turnsUnusable[x][y] + 1;
                                        q.offer(new int[]{nx, ny});
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        // Build graph
        int totalNodes = 2 * n * m + 2;
        s = 0;
        t = totalNodes - 1;
        for (int i = 0; i <= totalNodes; i++) {
            adj.get(i).clear();
        }
        for (int x = 0; x < n; x++) {
            for (int y = 0; y < m; y++) {
                char sciChar = sci[x].charAt(y);
                char reacChar = reac[x].charAt(y);
                if (sciChar >= '1' && sciChar <= '9') {
                    addEdge(s, getID(x, y), sciChar - '0');
                }
                if (reacChar >= '1' && reacChar <= '9') {
                    addEdge(n * m + getID(x, y), t, reacChar - '0');
                }
                for (int X = 0; X < n; X++) {
                    for (int Y = 0; Y < m; Y++) {
                        if (sciChar == 'Y' || sciChar == 'Z' || reac[X].charAt(Y) == 'Y' || reac[X].charAt(Y) == 'Z') continue;
                        for (int xx = 0; xx < n; xx++) {
                            for (int yy = 0; yy < m; yy++) {
                                if (xx == x && yy == y) continue;
                                if (sci[x].charAt(y) == 'Y' || sci[x].charAt(y) == 'Z' || reac[xx].charAt(yy) == 'Y' || reac[xx].charAt(yy) == 'Z') continue;
                                for (int[] v : visited) Arrays.fill(v, 0);
                                Queue<int[]> q = new LinkedList<>();
                                q.offer(new int[]{x, y, 1});
                                visited[x][y] = 1;
                                boolean reached = false;
                                while (!q.isEmpty()) {
                                    int[] curr = q.poll();
                                    int xx2 = curr[0], yy2 = curr[1], t_curr = curr[2];
                                    if (xx2 == X && yy2 == Y) {
                                        reached = true;
                                        break;
                                    }
                                    if (t_curr >= turnsUnusable[xx2][yy2] || t_curr >= T) continue;
                                    for (int dx = -1; dx <= 1; dx++) {
                                        for (int dy = -1; dy <= 1; dy++) {
                                            if (Math.abs(dx) + Math.abs(dy) == 1) {
                                                int nx = xx2 + dx, ny = yy2 + dy;
                                                if (validPos(nx, ny) && visited[nx][ny] == 0 && sci[nx].charAt(ny) != 'Y' && sci[nx].charAt(ny) != 'Z' && t_curr + 1 <= turnsUnusable[nx][ny]) {
                                                    visited[nx][ny] = 1;
                                                    q.offer(new int[]{nx, ny, t_curr + 1});
                                                }
                                            }
                                        }
                                    }
                                }
                                if (reached) {
                                    addEdge(getID(x, y), n * m + getID(X, Y), (int) INF_VAL);
                                }
                            }
                        }
                    }
                }
            }
        }
        long maxFlowVal = maxFlow();
        System.out.println(maxFlowVal);
    }
}

